# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
from decimal import Decimal

from apps.assessments.scoring import ScoredCriterion, WeightedPercentStrategy

D = Decimal
strategy = WeightedPercentStrategy()


def item(score, maximum=10, weight=1):
    return ScoredCriterion(D(score), D(maximum), D(weight))


def test_form_percent_is_weighted():
    # 8/10 weight 1 and 6/10 weight 1 -> 70%
    assert strategy.form_percent([item(8), item(6)]) == D("70.00")
    # weight 3 on a perfect score pulls the result up: (10*3 + 5*1) / 4 = 87.5
    assert strategy.form_percent([item(10, weight=3), item(5)]) == D("87.50")


def test_form_percent_with_no_scored_criteria_is_zero():
    assert strategy.form_percent([]) == D("0.00")
    assert strategy.form_percent([item(5, weight=0)]) == D("0.00")


def test_combine_uses_form_weights():
    assert strategy.combine([(D("70"), D("60")), (D("80"), D("40"))]) == D("74.00")
    assert strategy.combine([(D("100"), D("100"))]) == D("100.00")


def test_grade_picks_the_highest_band_not_above_the_percent():
    bands = [(D("0"), "F"), (D("70"), "A"), (D("60"), "B")]
    assert strategy.grade(D("74"), bands) == "A"
    assert strategy.grade(D("70"), bands) == "A"
    assert strategy.grade(D("69.99"), bands) == "B"
    assert strategy.grade(D("0"), bands) == "F"
    assert strategy.grade(D("50"), [(D("60"), "B")]) is None
